    public static String regionFor(String postcode, String city) {
        String region = regionFromPostcode(postcode);
        if (region != null) {
            return region;
        }
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }

    /** Region whose range contains the given postcode, or {@code null} when the postcode is
     * absent, not 4 digits, or in no known range. */
    private static String regionFromPostcode(String postcode) {
        if (postcode == null || !postcode.matches("[0-9]{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
